C_INFO = "\x1b[34m[INFO]\x1b[0m"
C_WARN = "\x1b[33m[WARN]\x1b[0m"
C_ERR = "\x1b[31m[ERROR]\x1b[0m"
C_OK = "\x1b[32m[SUCCESS]\x1b[0m"


def log_info(msg: str) -> None:
