# Index helpers ---------------------------------------------------------------

_LONG: dict[str, dict] = {a["name"]: a for a in ARGS}
_SHORT: dict[str, dict] = {a["short"]: a for a in ARGS if a.get("short")}


# Usage helpers ---------------------------------------------------------------

def _arg_signature(spec: dict) -> str:
    """Form used in `Usage:` lines like `--from-code [<Code>]`."""
    long = spec["name"]
    if spec["takes"] == "none":
        return long
    var = spec.get("var", "VALUE")
    if spec["takes"] == "optional":
        return f"{long} [<{var}>]"
    if spec["takes"] == "many":
        return f"{long} <{var}>..."
    return f"{long} <{var}>"


def usage_default() -> str:
    return f"Usage: {PROG} [OPTIONS] --output <OUTPUT>"


def usage_missing(required_signs: list[str]) -> str:
    parts = [PROG] + required_signs
    return "Usage: " + " ".join(parts)


# Help output -----------------------------------------------------------------

def _arg_header(spec: dict) -> str:
    parts = []
    if spec.get("short"):
        parts.append(f"{spec['short']},")
        prefix = "  "
    else:
        parts.append("  ")
        prefix = "  "
    parts.append(spec["name"])
    sig = ""
    if spec["takes"] == "required":
        sig = f" <{spec['var']}>"
    elif spec["takes"] == "optional":
        sig = f" [<{spec['var']}>]"
    elif spec["takes"] == "many":
        sig = f" <{spec['var']}>..."
    header = prefix + " ".join(parts) + sig
    return header


def print_help(long: bool) -> None:
    lines = [DESCRIPTION, "", usage_default(), "", "Options:"]

    for i, spec in enumerate(ARGS):
        header = _arg_header(spec)
        lines.append(header)

        help_text = spec.get("help_long" if long else "help_short")
        if help_text is None:
            help_text = spec.get("help", "")

        annotations: list[str] = []
        if "default" in spec:
            annotations.append(f"[default: {spec['default']}]")
        if "possible_values" in spec:
            annotations.append(
                "[possible values: " + ", ".join(spec["possible_values"]) + "]"
            )

        if long:
            if help_text or annotations:
                if help_text:
                    for ln in help_text.split("\n"):
                        lines.append("          " + ln)
                if annotations:
                    if help_text:
                        lines.append("          ")
                    for ann in annotations:
                        lines.append("          " + ann)
            else:
                lines.append("          ")
        else:
            joined = help_text
            if annotations:
                if joined:
                    joined = joined + " " + " ".join(annotations)
                else:
                    joined = " ".join(annotations)
            lines.append("          " + (joined or ""))

        # no blank line between options in short, but blank line between in long
        if long and i != len(ARGS) - 1:
            lines.append("")

    print("\n".join(lines))


# Error helpers ---------------------------------------------------------------

def _similar_arg(bad: str) -> str | None:
    longs = [a["name"] for a in ARGS]
    m = get_close_matches(bad, longs, n=1, cutoff=0.5)
    if m:
        return m[0]
    # fall back to substring match
    stripped = bad.lstrip("-")
    if len(stripped) >= 2:
        for a in ARGS:
            name = a["name"]
            if stripped and stripped in name:
                return name
    return None


def _usage_after_error(provided: list[str], extra_sig: str | None = None) -> str:
    """Build usage line shown below a clap-style error message.

    If `provided` is non-empty we show all provided arg signatures plus --output.
    Otherwise we show `[OPTIONS] --output <OUTPUT>` (generic) or just
    `--output <OUTPUT>` when no options were supplied at all.
    """
    signs: list[str] = ["--output <OUTPUT>"]
    for p in provided:
        if p == "--output":
            continue
        spec = _LONG.get(p)
        if spec:
            signs.append(_arg_signature(spec))
    if extra_sig:
        signs.append(extra_sig)
    return "Usage: " + " ".join([PROG] + signs)


def clap_error(message: str, usage: str) -> None:
    sys.stderr.write(f"error: {message}\n\n")
    sys.stderr.write(usage + "\n\n")
    sys.stderr.write("For more information, try '--help'.\n")
    sys.exit(2)


# Argument parsing ------------------------------------------------------------

class ParsedArgs:
    def __init__(self) -> None:
        self.values: dict[str, object] = {}
        self.provided: list[str] = []  # long names, in order encountered


def parse_argv(argv: list[str]) -> ParsedArgs:
    pa = ParsedArgs()
    i = 0
    # Track how we reached a value so error messages can reflect the original
    # representation of the option.
    seen_long: set[str] = set()

    def record(spec: dict, value):
        long = spec["name"]
        if spec["takes"] == "many":
            pa.values.setdefault(long, []).append(value)
        else:
            if long in seen_long and spec["takes"] != "none":
                # Option doesn't allow repetition.
                sig = _arg_signature(spec)
                clap_error(
                    f"the argument '{sig}' cannot be used multiple times",
                    usage_default(),
                )
            pa.values[long] = value if spec["takes"] != "none" else True
        seen_long.add(long)
        if long not in pa.provided:
            pa.provided.append(long)

    while i < len(argv):
        a = argv[i]

        if a == "--":
            # pass-through (unused)
            i += 1
            continue

        if a.startswith("--"):
            # Split at '=' if present
            if "=" in a:
                name, val = a.split("=", 1)
                has_val = True
            else:
                name, val = a, None
                has_val = False

            if name not in _LONG:
                tip = _similar_arg(name)
                msg = f"unexpected argument '{a}' found"
                if tip:
                    msg += "\n\n  tip: a similar argument exists: " + repr(tip).replace('"', "'")
                tip_spec = _LONG.get(tip) if tip else None
                usage = _usage_after_error(
                    pa.provided, _arg_signature(tip_spec) if tip_spec else None,
                )
                if not tip:
                    usage = usage_default()
                clap_error(msg, usage)

            spec = _LONG[name]
            t = spec["takes"]
            if t == "none":
                if has_val:
                    clap_error(
                        f"unexpected value '{val}' for '{name}' found; no more were expected",
                        usage_default(),
                    )
                record(spec, True)
                i += 1
                continue
            if has_val:
                _validate_value(spec, val)
                record(spec, val)
                i += 1
                continue

            if t == "optional":
                # peek next
                if i + 1 < len(argv):
                    nxt = argv[i + 1]
                    if nxt.startswith("-") and nxt != "-":
                        record(spec, None)
                        i += 1
                        continue
                    record(spec, nxt)
                    i += 2
                    continue
                record(spec, None)
                i += 1
                continue

            # required or many
            if i + 1 >= len(argv):
                clap_error(
                    f"a value is required for '{_arg_signature(spec)}' but none was supplied",
                    usage_default(),
                )
            nxt = argv[i + 1]
            _validate_value(spec, nxt)
            record(spec, nxt)
            i += 2
            if t == "many":
                # consume additional non-option positionals
                while i < len(argv) and not argv[i].startswith("-"):
                    _validate_value(spec, argv[i])
                    record(spec, argv[i])
                    i += 1
            continue

        if a.startswith("-") and len(a) > 1 and a != "-":
            # Short option(s) -- may be clustered or have inline value.
            rest = a[1:]
            spec = _SHORT.get("-" + rest[0])
            if not spec:
                clap_error(
                    f"unexpected argument '{a}' found",
                    usage_default(),
                )
            t = spec["takes"]
            if t == "none":
                record(spec, True)
                if len(rest) > 1:
                    # Remaining chars are more short options.
                    argv = argv[:i + 1] + ["-" + rest[1:]] + argv[i + 1:]
                i += 1
                continue
            # takes value
            if len(rest) > 1:
                val = rest[1:]
                _validate_value(spec, val)
                record(spec, val)
                i += 1
                continue
            # optional, look ahead
            if t == "optional":
                if i + 1 < len(argv):
                    nxt = argv[i + 1]
                    if nxt.startswith("-") and nxt != "-":
                        record(spec, None)
                        i += 1
                        continue
                    record(spec, nxt)
                    i += 2
                    continue
                record(spec, None)
                i += 1
                continue
            # required / many
            if i + 1 >= len(argv):
                clap_error(
                    f"a value is required for '{_arg_signature(spec)}' but none was supplied",
                    usage_default(),
                )
            nxt = argv[i + 1]
            _validate_value(spec, nxt)
            record(spec, nxt)
            i += 2
            if t == "many":
                while i < len(argv) and not argv[i].startswith("-"):
                    _validate_value(spec, argv[i])
                    record(spec, argv[i])
                    i += 1
            continue

        # Positional ("foo", "-")
        clap_error(f"unexpected argument '{a}' found", usage_default())

    return pa


def _validate_value(spec: dict, val: str) -> None:
    possible = spec.get("possible_values")
    if possible and val not in possible:
        sig = spec["name"] + (" <" + spec["var"] + ">" if spec.get("var") else "")
        msg = (
            f"invalid value '{val}' for '{sig}'\n  "
            f"[possible values: {', '.join(possible)}]"
        )
        sys.stderr.write(f"error: {msg}\n\n")
        sys.stderr.write("For more information, try '--help'.\n")
        sys.exit(2)

    vt = spec.get("value_type")
    sig = spec["name"] + (" <" + spec["var"] + ">" if spec.get("var") else "")
    if vt == "uint":
        try:
            int(val)
        except ValueError:
            sys.stderr.write(
                f"error: invalid value '{val}' for '{sig}': invalid digit found in string\n\n"
            )
            sys.stderr.write("For more information, try '--help'.\n")
            sys.exit(2)
    elif vt == "float":
        try:
            float(val)
        except ValueError:
            sys.stderr.write(
                f"error: invalid value '{val}' for '{sig}': invalid float literal\n\n"
            )
            sys.stderr.write("For more information, try '--help'.\n")
            sys.exit(2)


# Config ----------------------------------------------------------------------

DEFAULT_CONFIG = {
