# Usage helpers ---------------------------------------------------------------

def _arg_signature(spec: dict) -> str:
    """Form used in `Usage:` lines like `--from-code [<Code>]`."""
    long = spec["name"]
    if spec["takes"] == "none":
        return long
    var = spec.get("var", "VALUE")
    if spec["takes"] == "optional":
        return f"{long} [<{var}>]"
    if spec["takes"] == "many":
        return f"{long} <{var}>..."
    return f"{long} <{var}>"


def usage_default() -> str:
    return f"Usage: {PROG} [OPTIONS] --output <OUTPUT>"


def usage_missing(required_signs: list[str]) -> str:
    parts = [PROG] + required_signs
    return "Usage: " + " ".join(parts)


# Help output -----------------------------------------------------------------

def _arg_header(spec: dict) -> str:
    parts = []
    if spec.get("short"):
        parts.append(f"{spec['short']},")
        prefix = "  "
    else:
        parts.append("  ")
        prefix = "  "
    parts.append(spec["name"])
    sig = ""
    if spec["takes"] == "required":
        sig = f" <{spec['var']}>"
    elif spec["takes"] == "optional":
        sig = f" [<{spec['var']}>]"
    elif spec["takes"] == "many":
        sig = f" <{spec['var']}>..."
    header = prefix + " ".join(parts) + sig
    return header


def print_help(long: bool) -> None:
    lines = [DESCRIPTION, "", usage_default(), "", "Options:"]

