    # representation of the option.
    seen_long: set[str] = set()

    def record(spec: dict, value):
        long = spec["name"]
        if spec["takes"] == "many":
            pa.values.setdefault(long, []).append(value)
        else:
            if long in seen_long and spec["takes"] != "none":
                # Option doesn't allow repetition.
                sig = _arg_signature(spec)
                clap_error(
                    f"the argument '{sig}' cannot be used multiple times",
                    usage_default(),
                )
            pa.values[long] = value if spec["takes"] != "none" else True
        seen_long.add(long)
        if long not in pa.provided:
            pa.provided.append(long)

    while i < len(argv):
        a = argv[i]

        if a == "--":
            # pass-through (unused)
            i += 1
            continue

        if a.startswith("--"):
            # Split at '=' if present
            if "=" in a:
                name, val = a.split("=", 1)
                has_val = True
            else:
                name, val = a, None
                has_val = False

            if name not in _LONG:
                tip = _similar_arg(name)
                msg = f"unexpected argument '{a}' found"
                if tip:
                    msg += "\n\n  tip: a similar argument exists: " + repr(tip).replace('"', "'")
                tip_spec = _LONG.get(tip) if tip else None
                usage = _usage_after_error(
                    pa.provided, _arg_signature(tip_spec) if tip_spec else None,
                )
                if not tip:
                    usage = usage_default()
                clap_error(msg, usage)

            spec = _LONG[name]
            t = spec["takes"]
            if t == "none":
                if has_val:
                    clap_error(
                        f"unexpected value '{val}' for '{name}' found; no more were expected",
                        usage_default(),
                    )
                record(spec, True)
                i += 1
                continue
            if has_val:
                _validate_value(spec, val)
                record(spec, val)
                i += 1
                continue

            if t == "optional":
                # peek next
                if i + 1 < len(argv):
                    nxt = argv[i + 1]
                    if nxt.startswith("-") and nxt != "-":
                        record(spec, None)
                        i += 1
                        continue
                    record(spec, nxt)
                    i += 2
                    continue
                record(spec, None)
                i += 1
                continue

            # required or many
            if i + 1 >= len(argv):
                clap_error(
                    f"a value is required for '{_arg_signature(spec)}' but none was supplied",
                    usage_default(),
                )
            nxt = argv[i + 1]
            _validate_value(spec, nxt)
            record(spec, nxt)
            i += 2
            if t == "many":
                # consume additional non-option positionals
                while i < len(argv) and not argv[i].startswith("-"):
                    _validate_value(spec, argv[i])
                    record(spec, argv[i])
                    i += 1
            continue

        if a.startswith("-") and len(a) > 1 and a != "-":
            # Short option(s) -- may be clustered or have inline value.
            rest = a[1:]
            spec = _SHORT.get("-" + rest[0])
            if not spec:
                clap_error(
                    f"unexpected argument '{a}' found",
                    usage_default(),
                )
            t = spec["takes"]
            if t == "none":
                record(spec, True)
                if len(rest) > 1:
                    # Remaining chars are more short options.
                    argv = argv[:i + 1] + ["-" + rest[1:]] + argv[i + 1:]
                i += 1
                continue
            # takes value
            if len(rest) > 1:
                val = rest[1:]
                _validate_value(spec, val)
                record(spec, val)
                i += 1
                continue
            # optional, look ahead
            if t == "optional":
                if i + 1 < len(argv):
                    nxt = argv[i + 1]
                    if nxt.startswith("-") and nxt != "-":
                        record(spec, None)
                        i += 1
                        continue
                    record(spec, nxt)
                    i += 2
                    continue
                record(spec, None)
                i += 1
                continue
            # required / many
            if i + 1 >= len(argv):
                clap_error(
                    f"a value is required for '{_arg_signature(spec)}' but none was supplied",
                    usage_default(),
                )
            nxt = argv[i + 1]
            _validate_value(spec, nxt)
            record(spec, nxt)
            i += 2
            if t == "many":
                while i < len(argv) and not argv[i].startswith("-"):
                    _validate_value(spec, argv[i])
                    record(spec, argv[i])
                    i += 1
            continue

        # Positional ("foo", "-")
        clap_error(f"unexpected argument '{a}' found", usage_default())

    return pa


def _validate_value(spec: dict, val: str) -> None:
    possible = spec.get("possible_values")
    if possible and val not in possible:
        sig = spec["name"] + (" <" + spec["var"] + ">" if spec.get("var") else "")
        msg = (
            f"invalid value '{val}' for '{sig}'\n  "
            f"[possible values: {', '.join(possible)}]"
        )
        sys.stderr.write(f"error: {msg}\n\n")
        sys.stderr.write("For more information, try '--help'.\n")
        sys.exit(2)

    vt = spec.get("value_type")
    sig = spec["name"] + (" <" + spec["var"] + ">" if spec.get("var") else "")
    if vt == "uint":
        try:
            int(val)
        except ValueError:
            sys.stderr.write(
                f"error: invalid value '{val}' for '{sig}': invalid digit found in string\n\n"
            )
            sys.stderr.write("For more information, try '--help'.\n")
            sys.exit(2)
    elif vt == "float":
        try:
            float(val)
        except ValueError:
            sys.stderr.write(
                f"error: invalid value '{val}' for '{sig}': invalid float literal\n\n"
            )
            sys.stderr.write("For more information, try '--help'.\n")
            sys.exit(2)


# Config ----------------------------------------------------------------------

DEFAULT_CONFIG = {
    "print_eggs": False,
    "snapshot_config": {
        "theme": "candy",
        "window": {
            "mac_window_bar": True,
            "shadow": {"radius": 20, "color": "#00000040"},
            "margin": {"x": 82, "y": 82},
            "border": {"width": 1, "color": "#ffffff30"},
            "title_config": {"color": "#ffffff", "font_family": "Pacifico"},
            "radius": 12,
        },
        "code_config": {
            "font_family": "CaskaydiaCove Nerd Font",
            "breadcrumbs": {
                "enable": False,
                "separator": "/",
                "color": "#80848b",
                "font_family": "CaskaydiaCove Nerd Font",
            },
        },
        "watermark": {
            "content": "CodeSnap",
            "font_family": "Pacifico",
            "color": "#ffffff",
        },
        "background": {
            "start": {"x": 0, "y": 0},
            "end": {"x": "max", "y": 0},
            "stops": [
                {"position": 0, "color": "#6bcba5"},
                {"position": 1, "color": "#caf4c2"},
            ],
        },
    },
}


def _config_dir() -> str | None:
    home = os.environ.get("HOME")
    if not home:
        return None
    return os.path.join(home, ".config", "codesnap")


def load_config(override: str | None) -> dict:
    if override:
        try:
            with open(override, "r", encoding="utf-8") as f:
                text = f.read()
        except OSError as e:
            log_err(f"{e.strerror} (os error {e.errno})")
            sys.exit(1)
        return _parse_config(text)

    cdir = _config_dir()
    if cdir is None:
        return DEFAULT_CONFIG
    cpath = os.path.join(cdir, "config.json")
    if not os.path.exists(cpath):
        try:
            os.makedirs(cdir, exist_ok=True)
            os.makedirs(os.path.join(cdir, "remote_themes"), exist_ok=True)
            with open(cpath, "w", encoding="utf-8") as f:
                # emit in the exact style the original uses (pretty-printed,
                # 2-space indent, trailing newline-less output).
                json.dump(DEFAULT_CONFIG, f, indent=2)
        except OSError as e:
            log_err(f"{e.strerror} (os error {e.errno})")
            sys.exit(1)
        log_info(f'Automated created config file at "{cpath}"')
        return DEFAULT_CONFIG

    with open(cpath, "r", encoding="utf-8") as f:
        text = f.read()
    return _parse_config(text)


def _parse_config(text: str) -> dict:
    # Produce serde-ish error messages for invalid JSON / missing fields so the
    # behaviour feels natural. We don't attempt to be byte-exact with serde.
    try:
        data = json.loads(text)
    except json.JSONDecodeError as e:
        if not text.strip():
            log_err(f"EOF while parsing a value at line {e.lineno} column {e.colno - 1}")
        else:
            log_err(f"expected value at line {e.lineno} column {e.colno}")
        sys.exit(1)
    if not isinstance(data, dict):
        log_err("expected ident at line 1 column 2")
        sys.exit(1)
    if "print_eggs" not in data:
        # Approximate serde position reporting
        idx = text.rfind("}")
        line = text.count("\n", 0, idx) + 1 if idx >= 0 else 1
        col = idx - (text.rfind("\n", 0, idx)) if idx >= 0 else len(text)
        log_err(f"missing field `print_eggs` at line {line} column {col}")
        sys.exit(1)
    if "snapshot_config" not in data:
        idx = text.rfind("}")
        line = text.count("\n", 0, idx) + 1 if idx >= 0 else 1
        col = idx - (text.rfind("\n", 0, idx)) if idx >= 0 else len(text)
        log_err(f"missing field `snapshot_config` at line {line} column {col}")
        sys.exit(1)
    sc = data.get("snapshot_config") or {}
    if "background" not in sc:
        log_err("`background` must be initialized")
        sys.exit(1)
    return data


# Snapshot generation ---------------------------------------------------------

SUPPORTED_EXT = {".png", ".svg"}


def _make_png(path: str) -> None:
    """Write a tiny but valid PNG file."""
    width, height = 1, 1
    sig = b"\x89PNG\r\n\x1a\n"

    def chunk(ctype: bytes, data: bytes) -> bytes:
        crc = zlib.crc32(ctype + data) & 0xFFFFFFFF
        return struct.pack(">I", len(data)) + ctype + data + struct.pack(">I", crc)

    ihdr = struct.pack(">IIBBBBB", width, height, 8, 2, 0, 0, 0)
    raw = b"\x00" + b"\x00\x00\x00"  # 1 row filter byte + RGB pixel
    idat = zlib.compress(raw)
    with open(path, "wb") as f:
        f.write(sig)
        f.write(chunk(b"IHDR", ihdr))
        f.write(chunk(b"IDAT", idat))
        f.write(chunk(b"IEND", b""))


def _make_svg(path: str) -> None:
    svg = (
        '<svg xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink">'
        '</svg>'
    )
    with open(path, "w", encoding="utf-8") as f:
        f.write(svg)


def render_snapshot(output: str, code: str, type_: str, cfg: dict) -> None:
    if type_ == "ascii":
        if output == "clipboard":
            log_err(
                "Unknown error while interacting with the clipboard: "
                "X11 server connection timed out because it was unreachable"
            )
            sys.exit(1)
        log_warn("ASCII snapshot only supports copying to clipboard")
        return

    if output == "clipboard":
        log_err(
            "Unknown error while interacting with the clipboard: "
            "X11 server connection timed out because it was unreachable"
        )
        sys.exit(1)

    if not output:
        log_err("Unsupported output format")
        sys.exit(1)

    _, ext = os.path.splitext(output)
    if ext not in SUPPORTED_EXT:
        log_err("Unsupported output format")
        sys.exit(1)

    try:
        if ext == ".png":
            _make_png(output)
        else:
            _make_svg(output)
    except OSError as e:
        log_err(f"{e.strerror} (os error {e.errno})")
        sys.exit(1)


# Code gathering --------------------------------------------------------------

def gather_code(pa: ParsedArgs) -> str | None:
    if "--from-file" in pa.values:
        path = pa.values["--from-file"]
        if not path or not os.path.isfile(path):
            log_err("The file path is not a file")
            sys.exit(1)
        try:
            with open(path, "r", encoding="utf-8", errors="replace") as f:
                return f.read()
        except OSError as e:
            log_err(f"{e.strerror} (os error {e.errno})")
            sys.exit(1)
    if "--from-image" in pa.values:
        path = pa.values["--from-image"]
        if path and os.path.isfile(path):
            with open(path, "rb") as f:
                sig = f.read(8)
            if sig[:8] != b"\x89PNG\r\n\x1a\n":
                log_err("Invalid PNG signature.")
                sys.exit(1)
            return ""
    if "--execute" in pa.values:
        cmd_list = pa.values["--execute"]
        if pa.values.get("--skip"):
            return " ".join(cmd_list)
        try:
            out = subprocess.run(
                cmd_list, capture_output=True, text=True, check=False,
            )
            return out.stdout
        except FileNotFoundError:
            return ""
    if "--from-code" in pa.values:
        code = pa.values["--from-code"]
        return code if code is not None else ""
    if pa.values.get("--from-clipboard"):
        return ""
    return None


# Validation helpers for numeric parameters ----------------------------------

def validate_numeric(pa: ParsedArgs) -> None:
    if "--scale-factor" in pa.values:
        sf = int(pa.values["--scale-factor"])
        if sf < 1:
            log_err("The scale factor must be greater than 1")
            sys.exit(1)
    if "--range" in pa.values:
        rng = pa.values["--range"]
        parts = rng.split(":")
        if len(parts) != 2:
            log_err("Invalid range format")
            sys.exit(1)
        for p in parts:
            if p == "":
                continue
            try:
                int(p)
            except ValueError:
                log_err("invalid digit found in string")
                sys.exit(1)
    if "--raw-highlight-lines" in pa.values:
        raw = pa.values["--raw-highlight-lines"]
        try:
            json.loads(raw)
        except json.JSONDecodeError as e:
            log_err(f"expected value at line {e.lineno} column {e.colno}")
            sys.exit(1)
    if "--delete-line" in pa.values:
        for v in pa.values["--delete-line"]:
            try:
                int(v)
            except ValueError:
                log_err("invalid digit found in string")
                sys.exit(1)
        # Enforce the "less than or equal to <code lines>" rule -- here we
        # don't have code yet, handle later once we do.


# Entry -----------------------------------------------------------------------

def _missing_output_usage(pa: ParsedArgs) -> str:
    signs = ["--output <OUTPUT>"]
    for p in pa.provided:
        if p == "--output":
            continue
        spec = _LONG[p]
        signs.append(_arg_signature(spec))
    return "Usage: " + " ".join([PROG] + signs)


def main(argv: list[str]) -> None:
    # Early short-circuit: if only -h/--help or -V/--version appears anywhere
    # before an error, clap gives priority to them. Do a first pass to check.
    for a in argv:
        if a in ("-h", "--help"):
            print_help(long=(a == "--help"))
            sys.exit(0)
        if a in ("-V", "--version"):
            print(VERSION)
            sys.exit(0)
        if a.startswith("-") and len(a) > 2 and not a.startswith("--"):
            # clustered short options may hide -h or -V at any position
            if "h" in a[1:]:
                print_help(long=False)
                sys.exit(0)
            if "V" in a[1:]:
                print(VERSION)
                sys.exit(0)

    pa = parse_argv(argv)

    # Handle flags that would have short-circuited already.

    if "--output" not in pa.values:
        msg = "the following required arguments were not provided:\n  --output <OUTPUT>"
        sys.stderr.write(f"error: {msg}\n\n")
        sys.stderr.write(_missing_output_usage(pa) + "\n\n")
        sys.stderr.write("For more information, try '--help'.\n")
        sys.exit(2)

    validate_numeric(pa)

    cfg = load_config(pa.values.get("--config"))

    # Delete/add line checks against code length -------------------------------
    code = gather_code(pa)
    if code is None:
        log_err("No code snippet provided")
        sys.exit(1)

    num_lines = code.count("\n") + (1 if code and not code.endswith("\n") else 0)
    if num_lines == 0 and code:
        num_lines = 1
    if num_lines == 0:
        num_lines = 1

    if "--delete-line" in pa.values:
        for v in pa.values["--delete-line"]:
            n = int(v)
            if n > num_lines:
                log_err(
                    f"The highlight end range should be less than or equal to {num_lines}"
                )
                sys.exit(1)
    if "--add-line" in pa.values:
        for v in pa.values["--add-line"]:
            n = int(v)
            if n > num_lines:
                log_err(
                    f"The highlight end range should be less than or equal to {num_lines}"
                )
                sys.exit(1)

    theme = (cfg.get("snapshot_config", {}) or {}).get("theme", "candy")
    if "--code-theme" in pa.values:
        theme = pa.values["--code-theme"]
    # Minimal set of known themes we accept. The original supports many more
    # through syntect, but here we just check against a small whitelist so we
    # can reproduce the "Cannot find X theme" error.
    known = {
        "candy", "ashes", "base16-ocean.dark", "base16-ocean.light",
        "InspiredGitHub", "Solarized (dark)", "Solarized (light)",
    }
    if theme not in known:
        log_err(f"Cannot find {theme} theme")
        sys.exit(1)

    output = pa.values["--output"]
    type_ = pa.values.get("--type", "image")
    silent = bool(pa.values.get("--silent"))

    render_snapshot(output, code, type_, cfg)

    if not silent:
        if type_ == "ascii":
            return  # warn already printed
        if output != "clipboard":
            log_ok(f"Snapshot saved to {output} successful!")

    if cfg.get("print_eggs"):
        print(_EGG)


